export function taskTitle(route: Route): string { return route.view === 'task-edit' && !route.id ? '新建任务' : titles[route.view] || '任务'; }
const stamp = () => new Intl.DateTimeFormat('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date());
const artifactId = () => `artifact-${Date.now()}-${Math.random().toString(36).slice(2,7)}`;
const closed = (t: Task) => ['已完成','已取消','已拒绝'].includes(t.status);
const accepted = (t: Task) => ['已承接','进行中','待验收'].includes(t.status);
const latestArtifacts = (t:TaskRecord) => latestTaskArtifacts(t);
const artifactLabel = (a:Artifact) => a.sourceNeedsReview?'旧来源待复核':a.needsReview?'待核对':a.reviewedAt?'已核对':'未核对';
const taskState = (t:Task) => closed(t)?t.status:t.sourceNeedsReview?'来源待核对':t.status==='已承接'?'待做':t.status;
const readerKey = (space:string,id:string) => `task-reader:${space}:${id}`;
const deliveryKey = (space:string,t:TaskRecord) => `task-delivery:${space}:${t.id}:${t.version}`;
const usable = (v:string) => !!v.trim() && !/待选择|请选择|未设置|待确认|^未知$/.test(v.trim());
const validMoment = parseLocalMoment;
function dueText(v:string) { return !v||v==='无固定期限'?'无固定期限':v.replace('T',' ').replace(/^\d{4}-/,'').replace('-','月').replace(' ','日 '); }
function visibleSession(data:AppData,id:string) { const s=data.sessions.find(x=>x.id===id);return !!s&&(data.settings.space==='我的空间'||!!data.settings.toggles['shared-'+id]&&(data.settings.retention['session-space:'+id]||'Oops 产品团队')===data.settings.space); }
function materialsAvailable(data:AppData,t:TaskRecord) { return (t.materialRefs||[]).every(m=>!m.needsReview&&sourceAvailable(data,m)&&(!m.memoryId||data.memories.some(x=>x.id===m.memoryId&&!x.deleted&&x.confirmed&&!x.needsReview&&!x.tags.includes('待复核')&&provenanceAvailable(data,x.sources)))); }
const inquiries = taskInquiries;
function useTaskActions(t:TaskRecord) {
  const {data,update,navigate,toast}=useOops();
  function patch(change:Partial<TaskRecord>,activity?:string) { update(current=>({...current,tasks:current.tasks.map(x=>x.id===t.id?{...x,...change,activities:activity?[...x.activities,`${stamp()} · ${activity}`]:x.activities}:x)})); }
  function go(view:string,mode?:string) { navigate({view,id:t.id,mode}); }
  function apply(helper:(current:AppData)=>{data:AppData;error?:string},success?:string) { const result=helper(data);if(result.error){toast(result.error);return false;}update(current=>{const fresh=helper(current);if(fresh.error){toast(fresh.error);return current;}return fresh.data;});if(success)toast(success);return true; }
  function start(retry=false) {
    const result=beginGeneration(data,t.id,{retry});if(result.error||!result.token){toast(result.error||'准备未启动');return;}let token=result.token,cost=result.cost||0;
    update(current=>{const fresh=beginGeneration(current,t.id,{token,retry});if(fresh.error){toast(fresh.error);token='';return current;}cost=fresh.cost||cost;return fresh.data;});
    if(!token)return;setTimeout(()=>update(current=>finishLocalGeneration(current,t.id,token,cost)),2400);go('task-progress');
  }
  return {patch,go,start,apply};
}
function TaskSource({task}:{task:TaskRecord}) {
  const {data,navigate}=useOops();const session=data.sessions.find(s=>s.id===task.sourceSession),turn=sourceTurn(data,task);
  if(!task.sourceSession)return null;
  if(!session||!sourceAvailable(data,task))return <Notice tone="warning">原话已变化，先重新核对来源。</Notice>;
  return <Source title={session.title} time={turn?.time||task.sourceTime} onClick={()=>navigate({view:'session-transcript',id:session.id,mode:turn?.id||task.sourceId||task.sourceTime})}/>;
}
function TaskCard({task:t}:{task:TaskRecord}) {
  const {data,navigate}=useOops(),reason=taskBelongsToMe(data,t)?taskAttentionReason(t):taskIsMyAttention(data,t)?'到时间跟进这项工作':null,action=taskBelongsToMe(data,t)?taskPrimaryAction(t):{label:'查看跟进',view:'task-ask'};
  return <Card className="task-card task-list-card" onClick={()=>navigate({view:'task-detail',id:t.id})}><div className="section-title"><Badge tone={closed(t)?'gray':'purple'}>{taskState(t)}</Badge>{t.priority==='高'&&<Badge tone="rose">优先</Badge>}</div><h3>{t.title}</h3><p className="meta">{t.owner}负责 · {dueText(t.due)}</p><div className="task-card-next"><Icon name={reason?'flag':'arrow-right'} size={17}/><span>{reason||action?.label||'查看工作记录'}</span></div>{t.aiStatus==='准备中'&&<p className="meta task-assistant-line"><Icon name="sparkle" size={14}/>助手正在准备</p>}</Card>;
}
function dateGroup(t:TaskRecord) { if(closed(t))return '已结束';const due=validMoment(t.due),now=Date.now(),end=new Date();end.setHours(23,59,59,999);return due===undefined?'无固定期限':due<now?'已逾期':due<=end.getTime()?'今天':'之后'; }
