  const list=all.filter(related).filter(t=>mode==='待我处理'?taskIsMyAttention(data,t):mode==='助手工作'?t.aiStatus!=='未启动':true).filter(t=>filter==='全部状态'||(filter==='已结束'?closed(t):!closed(t))).filter(t=>priority==='全部优先级'||t.priority===priority.replace('优先级','')).filter(t=>`${t.title} ${t.description} ${t.requester} ${t.owner}`.toLowerCase().includes(query.trim().toLowerCase()));
  const order=mode==='待我处理'?['来源与要求待核对','需要决定','需要补齐与跟进','成果与结果待核对','需要跟进']:mode==='助手工作'?['正在准备','草稿就绪','需要处理','等待允许','已暂停与停止']:['已逾期','今天','之后','无固定期限','已结束'];
