  return <div className="stack"><Card><Badge>来自{t.requester}</Badge><h2>{t.title}</h2>{t.description&&<p>{t.description}</p>}<p className="meta">由我（{data.settings.name}）负责</p><TaskSource task={t}/></Card><Field label="期限（可留空）" value={due==='无固定期限'?'':due} onChange={setDue} placeholder="2026-10-09 17:00" hint="按当前设备本地时间"/><Check label="已核对目标，我负责这项工作" value={checked} onChange={setChecked}/>{error&&<p className="error-text">{error}</p>}<Button onClick={accept}>确认承接</Button><Button tone="secondary" onClick={()=>go('task-edit')}>先补充要求</Button><div className="action-grid"><Button tone="quiet" onClick={()=>go('task-transfer')}>建议转交</Button><Button tone="quiet" onClick={()=>go('task-reject')}>婉拒</Button></div></div>;
